<?php
class SocialPublisherService {
    private PDO $db;
    public function __construct(){$this->db=Database::getConnection();}
    public function processDue(int$limit=20,?int$tenantId=null): array {$limit=max(1,min(100,$limit));$processed=0;$published=0;$failed=0;for($i=0;$i<$limit;$i++){$target=$this->claimNext($tenantId);if(!$target)break;$processed++;try{$result=$this->publish($target);$this->complete($target,$result);$published++;}catch(Throwable$e){$this->fail($target,$e->getMessage());$failed++;}}return compact('processed','published','failed');}
    public function deleteRemote(int$targetId,int$tenantId,int$userId): void {$stmt=$this->db->prepare("SELECT t.*,p.tenant_id,c.external_account_id,c.access_token_encrypted,c.status connection_status FROM social_publication_targets t JOIN social_publications p ON p.id=t.publication_id JOIN social_connections c ON c.id=t.connection_id WHERE t.id=:id AND p.tenant_id=:tenant AND t.status='Published' AND t.remote_deleted_at IS NULL LIMIT 1");$stmt->execute(['id'=>$targetId,'tenant'=>$tenantId]);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row)throw new RuntimeException('Publication distante introuvable ou déjà supprimée.');if($row['provider']!=='facebook')throw new RuntimeException('La suppression automatique est disponible pour Facebook. Supprimez le contenu Instagram depuis Instagram.');$token=CryptoService::decrypt((string)$row['access_token_encrypted']);if($token===''||empty($row['external_post_id']))throw new RuntimeException('Jeton ou identifiant distant manquant.');try{$this->graph('DELETE','/'.(string)$row['external_post_id'],['access_token'=>$token]);$this->db->prepare('UPDATE social_publication_targets SET remote_deleted_at=NOW(),remote_delete_error=NULL WHERE id=:id')->execute(['id'=>$targetId]);$this->event($row,'remote_deleted','Deleted','Publication Facebook supprimée',['created_by'=>$userId]);}catch(Throwable$e){$this->db->prepare('UPDATE social_publication_targets SET remote_delete_error=:error WHERE id=:id')->execute(['id'=>$targetId,'error'=>mb_strimwidth($e->getMessage(),0,1000)]);throw$e;}}
    private function claimNext(?int$tenantId): ?array {$this->db->beginTransaction();try{$sql="SELECT t.*,p.tenant_id,p.client_id,p.project_id,p.master_title,p.master_caption,p.media_url,p.media_mime,p.scheduled_at,c.external_account_id,c.access_token_encrypted,c.status connection_status FROM social_publication_targets t JOIN social_publications p ON p.id=t.publication_id JOIN social_connections c ON c.id=t.connection_id WHERE t.status IN ('Queued','Retrying') AND t.next_attempt_at<=NOW() AND p.approval_status='Approved'";$params=[];if($tenantId!==null){$sql.=' AND p.tenant_id=:tenant';$params['tenant']=$tenantId;}$sql.=' ORDER BY t.next_attempt_at,t.id LIMIT 1 FOR UPDATE';$stmt=$this->db->prepare($sql);$stmt->execute($params);$row=$stmt->fetch(PDO::FETCH_ASSOC);if(!$row){$this->db->commit();return null;}$update=$this->db->prepare("UPDATE social_publication_targets SET status='Processing',attempts=attempts+1,updated_at=NOW() WHERE id=:id AND status IN ('Queued','Retrying')");$update->execute(['id'=>$row['id']]);if(!$update->rowCount()){$this->db->rollBack();return null;}$row['attempts']=(int)$row['attempts']+1;$this->db->commit();return$row;}catch(Throwable$e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}
    private function publish(array$row): array {$scope=$this->db->prepare('SELECT COUNT(*) total,SUM(project_id=:project) allowed FROM social_connection_projects WHERE connection_id=:connection AND tenant_id=:tenant');$scope->execute(['project'=>$row['project_id'],'connection'=>$row['connection_id'],'tenant'=>$row['tenant_id']]);$access=$scope->fetch(PDO::FETCH_ASSOC);if((int)$access['total']>0&&(int)$access['allowed']===0)throw new RuntimeException('Destination non autorisée pour ce projet.');if($row['connection_status']!=='Connected')throw new RuntimeException('Compte social non connecté.');$token=CryptoService::decrypt((string)$row['access_token_encrypted']);if($token==='')throw new RuntimeException('Jeton social absent ou illisible.');return match((string)$row['provider']){'facebook'=>$this->publishFacebook($row,$token),'instagram'=>$this->publishInstagram($row,$token),default=>throw new RuntimeException('Adaptateur '.$row['provider'].' non encore activé.')};}
    private function publishFacebook(array$row,string$token): array {$page=(string)$row['external_account_id'];if($page==='')throw new RuntimeException('Identifiant Page Facebook manquant.');$caption=(string)$row['adapted_caption'];$media=trim((string)$row['media_url']);$data=$media!==''?$this->graph('POST','/'.$page.'/photos',['url'=>$media,'caption'=>$caption,'access_token'=>$token]):$this->graph('POST','/'.$page.'/feed',['message'=>$caption,'access_token'=>$token]);$id=(string)($data['post_id']??$data['id']??'');if($id==='')throw new RuntimeException('Meta n a retourné aucun identifiant de publication.');return['external_post_id'=>$id,'external_post_url'=>'https://www.facebook.com/'.$id,'external_container_id'=>null];}
    private function publishInstagram(array$row,string$token): array {$account=(string)$row['external_account_id'];$media=trim((string)$row['media_url']);if($account==='')throw new RuntimeException('Identifiant Instagram Business manquant.');if($media===''||!str_starts_with(strtolower($media),'https://'))throw new RuntimeException('Instagram exige une URL d image publique en HTTPS.');if(!empty($row['media_mime'])&&$row['media_mime']!=='image/jpeg')throw new RuntimeException('Instagram accepte ici uniquement une image JPEG.');$container=$this->graph('POST','/'.$account.'/media',['image_url'=>$media,'caption'=>(string)$row['adapted_caption'],'access_token'=>$token]);$creation=(string)($container['id']??'');if($creation==='')throw new RuntimeException('Conteneur Instagram non créé.');$result=$this->graph('POST','/'.$account.'/media_publish',['creation_id'=>$creation,'access_token'=>$token]);$id=(string)($result['id']??'');if($id==='')throw new RuntimeException('Publication Instagram non confirmée.');$url='';try{$details=$this->graph('GET','/'.$id,['fields'=>'permalink','access_token'=>$token]);$url=(string)($details['permalink']??'');}catch(Throwable$ignored){}return['external_post_id'=>$id,'external_post_url'=>$url,'external_container_id'=>$creation];}
    private function graph(string$method,string$path,array$params): array {$token=(string)($params['access_token']??'');$secret=trim((string)config_env_value('META_CLIENT_SECRET',''));if($token!==''&&$secret!==''&&!isset($params['appsecret_proof']))$params['appsecret_proof']=hash_hmac('sha256',$token,$secret);$url='https://graph.facebook.com/'.$this->version().$path;$ch=curl_init();if($method==='GET')$url.='?'.http_build_query($params);curl_setopt_array($ch,[CURLOPT_URL=>$url,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>45,CURLOPT_HTTPHEADER=>['Accept: application/json']]);if($method==='POST')curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query($params)]);elseif($method==='DELETE')curl_setopt_array($ch,[CURLOPT_CUSTOMREQUEST=>'DELETE',CURLOPT_POSTFIELDS=>http_build_query($params)]);$body=curl_exec($ch);$status=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);$data=json_decode((string)$body,true);if($body===false||$status<200||$status>=300){$meta=is_array($data['error']??null)?$data['error']:[];$message=(string)($meta['message']??$error?:('Meta HTTP '.$status));if(isset($meta['code']))$message.=' [code '.$meta['code'].(isset($meta['error_subcode'])?'/'.$meta['error_subcode']:'').']';if(!empty($meta['is_transient']))$message.=' [transitoire]';throw new RuntimeException($message);}return is_array($data)?$data:[];}
    private function complete(array$row,array$result): void {$stmt=$this->db->prepare("UPDATE social_publication_targets SET status='Published',published_at=NOW(),external_post_id=:post,external_container_id=:container,external_post_url=:url,last_error=NULL WHERE id=:id AND status='Processing'");$stmt->execute(['post'=>$result['external_post_id']??null,'container'=>$result['external_container_id']??null,'url'=>$result['external_post_url']??null,'id'=>$row['id']]);$this->event($row,'published','Published','Publication envoyée avec succès',$result);}
    private function fail(array$row,string$error): void {$retry=(int)$row['attempts']<(int)$row['max_attempts'];$minutes=min(240,5*(2**max(0,(int)$row['attempts']-1)));$next=$retry?date('Y-m-d H:i:s',time()+$minutes*60):(string)$row['next_attempt_at'];$stmt=$this->db->prepare("UPDATE social_publication_targets SET status=:status,next_attempt_at=:next,last_error=:error WHERE id=:id AND status='Processing'");$stmt->execute(['status'=>$retry?'Retrying':'Failed','next'=>$next,'error'=>mb_strimwidth($error,0,1000),'id'=>$row['id']]);$this->event($row,$retry?'retry_scheduled':'failed',$retry?'Retrying':'Failed',$error,['attempt'=>$row['attempts'],'retry_minutes'=>$retry?$minutes:null]);}
    private function event(array$row,string$type,string$status,string$message,array$payload=[]): void {$stmt=$this->db->prepare('INSERT INTO social_publication_events(tenant_id,publication_id,target_id,event_type,status,message,payload_json) VALUES(:tenant,:publication,:target,:type,:status,:message,:payload)');$stmt->execute(['tenant'=>$row['tenant_id'],'publication'=>$row['publication_id'],'target'=>$row['id'],'type'=>$type,'status'=>$status,'message'=>mb_strimwidth($message,0,1000),'payload'=>json_encode($payload,JSON_UNESCAPED_SLASHES)]);}
    private function version(): string {$v=trim((string)config_env_value('META_GRAPH_VERSION','v23.0'));return preg_match('/^v\d+\.\d+$/',$v)?$v:'v23.0';}
}